window.CIVIL_SET_DATA["past-07"] = {"title":"Past Paper Set 7","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-07-001","src":"PAST-07-001","text":"The initial setting time of ordinary Portland cement is","options":[{"key":"a","text":"10 minutes"},{"key":"b","text":"30 minutes"},{"key":"c","text":"6 hours"},{"key":"d","text":"10 hours"}],"answer":"b","explanation":"IS 269 requires OPC to have an initial setting time of at least 30 minutes and a final setting time of at most 600 minutes (10 hours).","marks":1,"source":{"kind":"past","set":7,"question":1,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q1 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-07-007","src":"PAST-07-007","text":"Cement should be stored","options":[{"key":"a","text":"in wet condition on metal"},{"key":"b","text":"on ground"},{"key":"c","text":"on platform"},{"key":"d","text":"any of the above"}],"answer":"c","explanation":"Cement bags are stacked on a raised dry platform (wooden planks), clear of the floor and walls, in a damp-proof shed. This prevents it absorbing moisture and setting.","marks":1,"source":{"kind":"past","set":7,"question":7,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q7 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-07-008","src":"PAST-07-008","text":"Which metallic element is highest in cement?","options":[{"key":"a","text":"Calcium"},{"key":"b","text":"Aluminium"},{"key":"c","text":"Iron"},{"key":"d","text":"Sulphur"}],"answer":"a","explanation":"Lime (CaO) makes up about 60–67% of OPC, so calcium is by far the most abundant metallic element.","marks":1,"source":{"kind":"past","set":7,"question":8,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q8 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-07-015","src":"PAST-07-015","text":"The presence of sand in brick earth prevents","options":[{"key":"a","text":"cracking of bricks"},{"key":"b","text":"shrinkage of bricks"},{"key":"c","text":"warping of bricks"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"Free silica (sand) in the right proportion keeps the raw bricks from shrinking unevenly and warping during drying and burning, and gives them uniform shape. The key selects warping.","marks":1,"source":{"kind":"past","set":7,"question":15,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q15 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-07-034","src":"PAST-07-034","text":"A projecting piece usually provided to support a truss is","options":[{"key":"a","text":"cornice"},{"key":"b","text":"coping"},{"key":"c","text":"frieze"},{"key":"d","text":"lintel"}],"answer":"c","explanation":"The key identifies the frieze, the projecting band at the top of the wall below the eaves, as the member on which truss ends are supported. A cornice is a decorative projecting moulding at the top of the wall, coping is a capping that sheds rain from the top of a wall, and a lintel spans an opening.","marks":1,"source":{"kind":"past","set":7,"question":34,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q34 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-07-053","src":"PAST-07-053","text":"The radius of gyration of a rectangular section is not proportional to","options":[{"key":"a","text":"the square root of the moment of inertia"},{"key":"b","text":"the square root of the inverse of the area"},{"key":"c","text":"the square root of the moment of inertia divided by the area of the section"},{"key":"d","text":"none of these"}],"answer":"d","explanation":"Since \\[k = \\sqrt{\\dfrac{I}{A}}\\] \\(k\\) is proportional to \\(\\sqrt{I}\\), to \\(\\sqrt{1{/}A}\\) and to \\(\\sqrt{I{/}A}\\). None of the statements is false.","marks":1,"source":{"kind":"past","set":7,"question":53,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q53 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-07-054","src":"PAST-07-054","text":"Contour lines of different elevations can unite to form one line only in the case of","options":[{"key":"a","text":"a vertical cliff"},{"key":"b","text":"a saddle"},{"key":"c","text":"a water shed line"},{"key":"d","text":"a hill top"}],"answer":"a","explanation":"On a vertical cliff, contours of different elevations fall on the same plan position and merge into one line. They cross only at an overhanging cliff.","marks":1,"source":{"kind":"past","set":7,"question":54,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q54 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-07-080","src":"PAST-07-080","text":"The magnetic bearing of a line is 32° and the magnetic declination is 10° 15' W. The true bearing is","options":[{"key":"a","text":"21° 45'"},{"key":"b","text":"42° 15'"},{"key":"c","text":"42° 15' W"},{"key":"d","text":"21° 45' W"}],"answer":"a","explanation":"The true bearing is the magnetic bearing minus the west declination: \\[32^\\circ - 10^\\circ 15' = 21^\\circ 45'\\]","marks":2,"source":{"kind":"past","set":7,"question":80,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q80 · 2 marks"},"topic":"ACiE0105"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-07-005","src":"PAST-07-005","text":"A piston sampler is used for which type of soil?","options":[{"key":"a","text":"Very soft clay"},{"key":"b","text":"Clay"},{"key":"c","text":"Sand"},{"key":"d","text":"Rock"}],"answer":"a","explanation":"The piston in a stationary-piston sampler creates suction that holds very soft or sensitive clays and silts, which would otherwise slip out of an open tube.","marks":1,"source":{"kind":"past","set":7,"question":5,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q5 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-07-006","src":"PAST-07-006","text":"The ratio of settlement at any time 't' to the final settlement is known as","options":[{"key":"a","text":"coefficient of consolidation"},{"key":"b","text":"degree of consolidation"},{"key":"c","text":"consolidation index"},{"key":"d","text":"settlement ratio"}],"answer":"b","explanation":"The average degree of consolidation is \\[U = \\dfrac{S_t}{S_{final}}\\] It depends on the time factor \\(T_v = \\dfrac{c_vt}{d^2}\\).","marks":1,"source":{"kind":"past","set":7,"question":6,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q6 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-07-016","src":"PAST-07-016","text":"On wetting, cohesive soils","options":[{"key":"a","text":"lose permeability"},{"key":"b","text":"gain shear strength"},{"key":"c","text":"lose elasticity"},{"key":"d","text":"decrease their shear strength"}],"answer":"d","explanation":"Water softens clays: the water content rises, the consistency moves towards the liquid state, and suction and effective cohesion fall. The shear strength therefore decreases.","marks":1,"source":{"kind":"past","set":7,"question":16,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q16 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-07-032","src":"PAST-07-032","text":"The neutral stress in a soil mass is","options":[{"key":"a","text":"force per neutral area"},{"key":"b","text":"force per effective area"},{"key":"c","text":"stress taken up by the pore water"},{"key":"d","text":"stress taken up by solid particles"}],"answer":"c","explanation":"Neutral stress is the pore-water pressure \\(u\\). It acts equally in all directions and does not add to shear strength, while the effective stress \\[\\sigma' = \\sigma - u\\] is carried by the soil skeleton.","marks":1,"source":{"kind":"past","set":7,"question":32,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q32 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-07-035","src":"PAST-07-035","text":"For testing a saturated clay for shear strength, the test recommended is","options":[{"key":"a","text":"direct shear test"},{"key":"b","text":"tri-axial compression test"},{"key":"c","text":"unconfined compression test"},{"key":"d","text":"all the above"}],"answer":"c","explanation":"A saturated clay behaves as \\(\\phi_u = 0\\) in quick loading, so the simple unconfined compression test gives its undrained strength directly: \\[c_u = \\dfrac{q_u}{2}\\]","marks":1,"source":{"kind":"past","set":7,"question":35,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q35 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-07-052","src":"PAST-07-052","text":"A wall constructed with stones to protect slopes of cuttings in natural ground from the action of weathering agents is called","options":[{"key":"a","text":"retaining wall"},{"key":"b","text":"breast wall"},{"key":"c","text":"buttress"},{"key":"d","text":"parapet wall"}],"answer":"b","explanation":"A breast wall protects the face of a cut slope in natural ground from weathering and erosion. A retaining wall holds back earth fill.","marks":1,"source":{"kind":"past","set":7,"question":52,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q52 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-07-056","src":"PAST-07-056","text":"Pick up the correct statement from the following.","options":[{"key":"a","text":"Failure plane carries maximum shear stress"},{"key":"b","text":"Failure plane does not carry maximum shear stress"},{"key":"c","text":"Failure plane carries shear stress equal to maximum shear stress"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"By Mohr-Coulomb, failure occurs on the plane at \\(45^\\circ + \\dfrac{\\phi}{2}\\) to the major principal plane, where the shear stress reaches the shear strength. The maximum shear stress acts on the \\(45^\\circ\\) plane, so the failure plane does not carry it (unless \\(\\phi = 0\\)).","marks":1,"source":{"kind":"past","set":7,"question":56,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q56 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-07-067","src":"PAST-07-067","text":"The bearing capacity of soft clay in kPa is","options":[{"key":"a","text":"50"},{"key":"b","text":"100"},{"key":"c","text":"150"},{"key":"d","text":"200"}],"answer":"a","explanation":"Soft clay is weak and compressible, and its presumptive safe bearing value is low, of the order of 50 kPa (about 5 t per m<sup>2</sup>). Medium and stiff clays allow roughly 150-450 kPa.","marks":2,"source":{"kind":"past","set":7,"question":67,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q67 · 2 marks"},"topic":"ACiE0206"},{"id":"PAST-07-068","src":"PAST-07-068","text":"In an infinite slope, FOS = 1.5 and the angle of internal friction = 36°. Find the safe angle (of slope) in degrees.","options":[{"key":"a","text":"26"},{"key":"b","text":"30"},{"key":"c","text":"16"},{"key":"d","text":"20"}],"answer":"a","explanation":"For a cohesionless infinite slope, \\(\\text{FS} = \\dfrac{\\tan\\phi}{\\tan\\beta}\\). So \\[\\tan\\beta = \\dfrac{\\tan 36^\\circ}{1.5} = 0.484\\] giving \\(\\beta \\approx 26^\\circ\\).","marks":2,"source":{"kind":"past","set":7,"question":68,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q68 · 2 marks"},"topic":"ACiE0203"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-07-017","src":"PAST-07-017","text":"Which of the following has the minimum compressibility?","options":[{"key":"a","text":"Water at room temperature"},{"key":"b","text":"Air at room temperature"},{"key":"c","text":"Oxygen at room temperature"},{"key":"d","text":"Nitrogen at room temperature"}],"answer":"a","explanation":"Liquids are nearly incompressible (water's bulk modulus is about 2.1 GPa), while gases are highly compressible.","marks":1,"source":{"kind":"past","set":7,"question":17,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q17 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-07-031","src":"PAST-07-031","text":"A floating body attains stable equilibrium if its metacentre is","options":[{"key":"a","text":"at the centroid"},{"key":"b","text":"above the centroid"},{"key":"c","text":"below the centroid"},{"key":"d","text":"anywhere"}],"answer":"b","explanation":"A floating body is stable when its metacentre M lies above its centre of gravity G (positive GM). It is neutral when M coincides with G and unstable when M is below G.","marks":1,"source":{"kind":"past","set":7,"question":31,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q31 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-07-036","src":"PAST-07-036","text":"In which of the following conditions can the Bernoulli equation not be used?","options":[{"key":"a","text":"Viscous flow"},{"key":"b","text":"Incompressible flow"},{"key":"c","text":"Steady flow"},{"key":"d","text":"Laminar flow"}],"answer":"a","explanation":"Bernoulli's equation assumes ideal (non-viscous), steady, incompressible flow along a streamline. Viscous flow involves friction losses that the basic equation ignores.","marks":1,"source":{"kind":"past","set":7,"question":36,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q36 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-07-051","src":"PAST-07-051","text":"The frictional resistance of a pipe varies approximately with …… of the liquid.","options":[{"key":"a","text":"pressure"},{"key":"b","text":"velocity"},{"key":"c","text":"square of velocity"},{"key":"d","text":"cube of velocity"}],"answer":"c","explanation":"By Darcy-Weisbach, \\[h_f = \\dfrac{fLV^2}{2gD}\\] so frictional resistance in turbulent flow varies about as \\(V^2\\).","marks":1,"source":{"kind":"past","set":7,"question":51,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q51 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-07-057","src":"PAST-07-057","text":"When the flow in an open channel is gradually varied, the flow is said to be","options":[{"key":"a","text":"steady uniform flow"},{"key":"b","text":"steady non-uniform flow"},{"key":"c","text":"unsteady uniform flow"},{"key":"d","text":"unsteady non-uniform flow"}],"answer":"b","explanation":"Gradually varied flow (as in backwater curves) has depth changing slowly along the channel but not with time, so it is steady non-uniform flow.","marks":1,"source":{"kind":"past","set":7,"question":57,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q57 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-07-064","src":"PAST-07-064","text":"Two capillary tubes P and Q are dipped in water. The height of water level in capillary P is 2/3 of the height in capillary Q. The ratio of their diameters is","options":[{"key":"a","text":"2:3"},{"key":"b","text":"3:2"},{"key":"c","text":"3:4"},{"key":"d","text":"4:3"}],"answer":"b","explanation":"Capillary rise varies as \\(h \\propto \\dfrac{1}{d}\\), so \\[\\dfrac{d_P}{d_Q} = \\dfrac{h_Q}{h_P} = \\dfrac{3}{2}\\]","marks":2,"source":{"kind":"past","set":7,"question":64,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q64 · 2 marks"},"topic":"ACiE0301"},{"id":"PAST-07-065","src":"PAST-07-065","text":"The value of hydraulic radius in the most economical triangular channel is","options":[{"key":"a","text":"y/2"},{"key":"b","text":"y/2√2"},{"key":"c","text":"y/√2"},{"key":"d","text":"y/√3"}],"answer":"b","explanation":"The best triangular section has \\(45^\\circ\\) sides (1 to 1 slopes): \\(A = y^2\\) and \\(P = 2\\sqrt{2}\\,y\\), so \\[R = \\dfrac{A}{P} = \\dfrac{y}{2\\sqrt{2}}\\]","marks":2,"source":{"kind":"past","set":7,"question":65,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q65 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-07-079","src":"PAST-07-079","text":"What is the ratio of the velocity at the axis of the pipe to the mean velocity of flow in the case of pipe flow under viscous conditions?","options":[{"key":"a","text":"0.5"},{"key":"b","text":"0.67"},{"key":"c","text":"1"},{"key":"d","text":"2"}],"answer":"d","explanation":"Laminar (Hagen–Poiseuille) flow has a parabolic velocity profile, so the centreline velocity is twice the mean velocity.","marks":2,"source":{"kind":"past","set":7,"question":79,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q79 · 2 marks"},"topic":"ACiE0304"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-07-009","src":"PAST-07-009","text":"If a beam is subjected to a constant bending moment along its length, then the shear force will","options":[{"key":"a","text":"also have a constant value everywhere along its length"},{"key":"b","text":"be zero at all sections along the beam"},{"key":"c","text":"be maximum at the centre and zero at the ends"},{"key":"d","text":"be zero at the centre and maximum at the ends"}],"answer":"b","explanation":"Since \\(S = \\dfrac{dM}{dx}\\), a constant moment gives zero shear everywhere (pure bending).","marks":1,"source":{"kind":"past","set":7,"question":9,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q9 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-07-030","src":"PAST-07-030","text":"Along the principal plane subjected to the maximum principal stress","options":[{"key":"a","text":"maximum shear stress acts"},{"key":"b","text":"minimum shear stress acts"},{"key":"c","text":"no shear stress acts"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"Principal planes are, by definition, planes of zero shear stress. The maximum shear occurs on planes at 45° to them.","marks":1,"source":{"kind":"past","set":7,"question":30,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q30 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-07-037","src":"PAST-07-037","text":"A shaft is subjected to bending moment M and torque T simultaneously. The ratio of the maximum bending stress to the maximum shear stress developed in the shaft is","options":[{"key":"a","text":"M/T"},{"key":"b","text":"T/M"},{"key":"c","text":"2M/T"},{"key":"d","text":"2T/M"}],"answer":"c","explanation":"The bending and torsional stresses are \\[\\sigma_b = \\dfrac{32M}{\\pi d^3}, \\qquad \\tau = \\dfrac{16T}{\\pi d^3}\\] so \\(\\dfrac{\\sigma_b}{\\tau} = \\dfrac{2M}{T}\\).","marks":1,"source":{"kind":"past","set":7,"question":37,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q37 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-07-050","src":"PAST-07-050","text":"If the width of a simply supported beam carrying an isolated load at its centre is doubled, the deflection of the beam at the centre is changed by","options":[{"key":"a","text":"1/2"},{"key":"b","text":"1/8"},{"key":"c","text":"2"},{"key":"d","text":"8"}],"answer":"a","explanation":"The central deflection is \\[\\delta = \\dfrac{WL^3}{48EI}, \\qquad I = \\dfrac{bd^3}{12} \\propto b\\] so doubling the width halves the deflection, a change by \\(\\dfrac{1}{2}\\).","marks":1,"source":{"kind":"past","set":7,"question":50,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q50 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-07-058","src":"PAST-07-058","text":"In a plastic analysis of structures, the segment between any two successive plastic hinges is assumed to deform as","options":[{"key":"a","text":"a plastic material"},{"key":"b","text":"a rigid material"},{"key":"c","text":"an elastic material"},{"key":"d","text":"an inelastic material"}],"answer":"b","explanation":"In rigid–plastic collapse analysis, all rotation is concentrated at the plastic hinges, so the segments between them move as rigid bodies.","marks":1,"source":{"kind":"past","set":7,"question":58,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q58 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-07-061","src":"PAST-07-061","text":"A moment M is acting at the centre of a cantilever beam of length L. What will be the value of shear force and bending moment at the fixed end?","options":[{"key":"a","text":"0 and 0"},{"key":"b","text":"M and 0"},{"key":"c","text":"0 and M"},{"key":"d","text":"M/L and 0"}],"answer":"c","explanation":"A pure couple produces no vertical force, so the shear is zero everywhere. The moment between the fixed end and the point of the couple is M.","marks":2,"source":{"kind":"past","set":7,"question":61,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q61 · 2 marks"},"topic":"ACiE0401"},{"id":"PAST-07-066","src":"PAST-07-066","text":"The horizontal thrust in a two hinged semi-circular arch subjected to UDL of w kN/m over the left half span will be","options":[{"key":"a","text":"4wR/3π"},{"key":"b","text":"wR/2"},{"key":"c","text":"wR"},{"key":"d","text":"2wR/3π"}],"answer":"d","explanation":"For a two-hinged semicircular arch, UDL over the whole span gives \\[H = \\dfrac{4wR}{3\\pi}\\] Loading only half the span gives half of this, \\(\\dfrac{2wR}{3\\pi}\\).","marks":2,"source":{"kind":"past","set":7,"question":66,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q66 · 2 marks"},"topic":"ACiE0406"},{"id":"PAST-07-078","src":"PAST-07-078","text":"A simply supported beam 'A' of length l carries a central point load W. Another beam 'B' is loaded with a uniformly distributed load such that the total load on the beam is W. The ratio of maximum deflections between beams A and B is","options":[{"key":"a","text":"5/8"},{"key":"b","text":"8/5"},{"key":"c","text":"5/4"},{"key":"d","text":"4/5"}],"answer":"b","explanation":"The two central deflections are \\[\\delta_A = \\dfrac{Wl^3}{48EI}\\] \\[\\delta_B = \\dfrac{5Wl^3}{384EI}\\] so \\[\\dfrac{\\delta_A}{\\delta_B} = \\dfrac{384}{48 \\times 5} = \\dfrac{8}{5}\\]","marks":2,"source":{"kind":"past","set":7,"question":78,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q78 · 2 marks"},"topic":"ACiE0404"}]},{"name":"Design of Structures","questions":[{"id":"PAST-07-003","src":"PAST-07-003","text":"During ultimate shear failure, the resistance is provided by","options":[{"key":"a","text":"Shear reinforcement only"},{"key":"b","text":"Compression reinforcement only"},{"key":"c","text":"Both of these"},{"key":"d","text":"None of the above"}],"answer":"c","explanation":"At ultimate, shear is carried jointly by the concrete (uncracked compression zone, aggregate interlock and the dowel action of the longitudinal bars) and by the shear reinforcement (stirrups or bent bars).","marks":1,"source":{"kind":"past","set":7,"question":3,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q3 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-07-018","src":"PAST-07-018","text":"While compacting concrete by a mechanical vibrator, the slump should not exceed","options":[{"key":"a","text":"2.5 cm"},{"key":"b","text":"5.0 cm"},{"key":"c","text":"7.5 cm"},{"key":"d","text":"10 cm"}],"answer":"b","explanation":"Vibration works best on stiff, low-workability mixes. For mechanically vibrated concrete the slump is kept to about 50 mm or less; wetter mixes segregate and bleed under vibration.","marks":1,"source":{"kind":"past","set":7,"question":18,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q18 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-07-029","src":"PAST-07-029","text":"The maximum area of tension reinforcement in beams shall not exceed","options":[{"key":"a","text":"0.15%"},{"key":"b","text":"1.5%"},{"key":"c","text":"4%"},{"key":"d","text":"1%"}],"answer":"c","explanation":"IS 456 limits tension (and compression) steel in beams to 0.04bD (4%) each, to allow proper placing and compaction of concrete.","marks":1,"source":{"kind":"past","set":7,"question":29,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q29 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-07-033","src":"PAST-07-033","text":"The aggregate containing moisture in its pores and having its surface dry is known as","options":[{"key":"a","text":"moist aggregate"},{"key":"b","text":"very dry aggregate"},{"key":"c","text":"dry aggregate"},{"key":"d","text":"saturated surface dry aggregate"}],"answer":"d","explanation":"In the SSD state all the permeable pores are filled with water but the surface carries no free water, so the aggregate neither absorbs nor gives water to the mix.","marks":1,"source":{"kind":"past","set":7,"question":33,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q33 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-07-038","src":"PAST-07-038","text":"The minimum cube strength of concrete used for a pre-stressed member is","options":[{"key":"a","text":"50 kg/cm<sup>2</sup>"},{"key":"b","text":"150 kg/cm<sup>2</sup>"},{"key":"c","text":"250 kg/cm<sup>2</sup>"},{"key":"d","text":"350 kg/cm<sup>2</sup>"}],"answer":"d","explanation":"Prestressed concrete needs high-strength concrete: IS 1343 requires M30 for post-tensioned and M40 for pre-tensioned members. Among the options only 350 kg per cm<sup>2</sup> (about 35 MPa) is adequate.","marks":1,"source":{"kind":"past","set":7,"question":38,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q38 · 1 mark"},"topic":"ACiE0504"},{"id":"PAST-07-049","src":"PAST-07-049","text":"A fillet weld whose axis is parallel to the direction of the applied load is known as","options":[{"key":"a","text":"diagonal fillet weld"},{"key":"b","text":"end fillet weld"},{"key":"c","text":"side fillet weld"},{"key":"d","text":"all the above"}],"answer":"c","explanation":"A side (longitudinal) fillet weld runs parallel to the load and resists it in shear. An end (transverse) fillet is perpendicular to the load.","marks":1,"source":{"kind":"past","set":7,"question":49,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q49 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-07-077","src":"PAST-07-077","text":"What is the net sectional area of a steel plate 40 cm wide and 10 mm thick with one bolt, if the diameter of the bolt hole is 18 mm?","options":[{"key":"a","text":"38.2 cm<sup>2</sup>"},{"key":"b","text":"24 cm<sup>2</sup>"},{"key":"c","text":"578 mm<sup>2</sup>"},{"key":"d","text":"465 mm<sup>2</sup>"}],"answer":"a","explanation":"The net area is \\[\\begin{aligned} A_{net} &amp;= (b - d_h)t \\\\ &amp;= (400 - 18) \\times 10 \\\\ &amp;= 3820\\ \\text{mm}^2 = 38.2\\ \\text{cm}^2 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":7,"question":77,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q77 · 2 marks"},"topic":"ACiE0505"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-07-019","src":"PAST-07-019","text":"By boiling water, hardness can be removed if it is due to","options":[{"key":"a","text":"calcium sulphate"},{"key":"b","text":"magnesium sulphate"},{"key":"c","text":"calcium nitrate"},{"key":"d","text":"calcium bicarbonate"}],"answer":"d","explanation":"Boiling decomposes bicarbonates: Ca(HCO<sub>3</sub>)<sub>2</sub> → CaCO<sub>3</sub>↓ + CO<sub>2</sub> + H<sub>2</sub>O. This is temporary (carbonate) hardness; sulphates and nitrates give permanent hardness.","marks":1,"source":{"kind":"past","set":7,"question":19,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q19 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-07-028","src":"PAST-07-028","text":"Which of the following pipe fittings provides a deviation of 90° in the pipework system?","options":[{"key":"a","text":"Elbow"},{"key":"b","text":"Tee branch"},{"key":"c","text":"Eccentric reducer"},{"key":"d","text":"Plug"}],"answer":"a","explanation":"An elbow (bend) changes the direction of the pipeline, commonly by 90° or 45°. A tee makes a branch, a reducer changes size and a plug closes an end.","marks":1,"source":{"kind":"past","set":7,"question":28,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q28 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-07-039","src":"PAST-07-039","text":"Zeolite used in the zeolite softening process for the treatment of hard water gets exhausted after a certain time of usage but can be regenerated by flushing it with","options":[{"key":"a","text":"10% calcium chloride solution"},{"key":"b","text":"10% magnesium sulphate solution"},{"key":"c","text":"10% magnesium chloride solution"},{"key":"d","text":"10% sodium chloride solution"}],"answer":"d","explanation":"Exhausted Ca- and Mg-zeolite is regenerated with brine (about 10% NaCl): the sodium ions replace the calcium and magnesium, which are washed out as chlorides.","marks":1,"source":{"kind":"past","set":7,"question":39,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q39 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-07-048","src":"PAST-07-048","text":"A manhole is classified as shallow if its depth is between","options":[{"key":"a","text":"0.4 to 0.5 m"},{"key":"b","text":"0.5 to 0.7 m"},{"key":"c","text":"0.7 to 0.9 m"},{"key":"d","text":"0.9 to 1.2 m"}],"answer":"c","explanation":"Shallow manholes are about 0.7–0.9 m deep, normal manholes about 1.5 m, and deep manholes more than that.","marks":1,"source":{"kind":"past","set":7,"question":48,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q48 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-07-055","src":"PAST-07-055","text":"The detention period in a septic tank is assumed as","options":[{"key":"a","text":"2 hrs"},{"key":"b","text":"12 hrs"},{"key":"c","text":"24 hrs"},{"key":"d","text":"28 hrs"}],"answer":"c","explanation":"A septic tank is normally designed for about 24 hours of detention, enough for the solids to settle and partly digest.","marks":1,"source":{"kind":"past","set":7,"question":55,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q55 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-07-070","src":"PAST-07-070","text":"What is the fire demand of a city of 1 lakh population by Buston's formula?","options":[{"key":"a","text":"5663 l/min"},{"key":"b","text":"56630 l/min"},{"key":"c","text":"566300 l/min"},{"key":"d","text":"5663000 l/min"}],"answer":"b","explanation":"Buston's formula, with \\(P\\) in thousands and \\(Q\\) in litres per minute, is \\[Q = 5663\\sqrt{P}\\] For \\(P = 100\\), \\[Q = 5663 \\times 10 = 56{,}630\\] litres per minute.","marks":2,"source":{"kind":"past","set":7,"question":70,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q70 · 2 marks"},"topic":"ACiE0601"},{"id":"PAST-07-076","src":"PAST-07-076","text":"The moisture content of a sludge is reduced from 90% to 80% in a sludge digestion tank. The percentage decrease in the volume of sludge is","options":[{"key":"a","text":"25%"},{"key":"b","text":"50"},{"key":"c","text":"10%"},{"key":"d","text":"5%"}],"answer":"b","explanation":"The solids stay constant, so \\[\\dfrac{V_2}{V_1} = \\dfrac{100 - 90}{100 - 80} = \\dfrac{10}{20} = 0.5\\] The volume decreases by 50%.","marks":2,"source":{"kind":"past","set":7,"question":76,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q76 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-07-020","src":"PAST-07-020","text":"Canal irrigation is generally preferred in","options":[{"key":"a","text":"non-alluvial canal"},{"key":"b","text":"non-perennial canal"},{"key":"c","text":"feeder canal"},{"key":"d","text":"alluvial canal"}],"answer":"d","explanation":"Flat, fertile alluvial plains with perennial rivers are best suited to canal irrigation, which is why the large canal systems are in alluvial regions.","marks":1,"source":{"kind":"past","set":7,"question":20,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q20 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-07-027","src":"PAST-07-027","text":"Which of the following conditions is NOT applicable to a true regime?","options":[{"key":"a","text":"Channel can be scoured more easily than it can be deposited"},{"key":"b","text":"Silt grade is constant"},{"key":"c","text":"Silt charge is constant"},{"key":"d","text":"Discharge is constant"}],"answer":"a","explanation":"Lacey's true regime needs constant discharge, constant silt charge and grade, and incoherent alluvium that can be scoured as easily as it is deposited. Statement (a) breaks that equality.","marks":1,"source":{"kind":"past","set":7,"question":27,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q27 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-07-040","src":"PAST-07-040","text":"According to Bligh's creep theory, percolating water flows along","options":[{"key":"a","text":"a straight path under the foundation of the dam"},{"key":"b","text":"a circular path under the foundation of the dam"},{"key":"c","text":"the outline of the base of the foundation of the dam"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"Bligh assumed seepage creeps along the contact surface of the base profile and the sheet piles (the creep length), with head lost uniformly along that path.","marks":1,"source":{"kind":"past","set":7,"question":40,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q40 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-07-047","src":"PAST-07-047","text":"Guide banks are provided to","options":[{"key":"a","text":"train the flow of a river along a specified course"},{"key":"b","text":"reduce the peak flood discharge"},{"key":"c","text":"confine the width of the river"},{"key":"d","text":"increase the water way"}],"answer":"a","explanation":"Guide banks guide the river through the bridge or barrage opening along a fixed course, preventing outflanking and attack on the approaches.","marks":1,"source":{"kind":"past","set":7,"question":47,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q47 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-07-059","src":"PAST-07-059","text":"The top soil of a water-logged field becomes more alkaline and infertile if its pH value is","options":[{"key":"a","text":"6"},{"key":"b","text":"8"},{"key":"c","text":"9"},{"key":"d","text":"11"}],"answer":"d","explanation":"Waterlogging brings salts to the surface. Soils with pH above about 8.5 are alkaline, and at about 11 they are highly alkaline and practically infertile.","marks":1,"source":{"kind":"past","set":7,"question":59,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q59 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-07-062","src":"PAST-07-062","text":"The discharge passing through an ogee spillway is 90 m<sup>3</sup>/s. Calculate the length of crest if the head over the crest is 1.6 m (take C = 1.7).","options":[{"key":"a","text":"22 m"},{"key":"b","text":"24 m"},{"key":"c","text":"26 m"},{"key":"d","text":"28 m"}],"answer":"c","explanation":"The crest length is \\[\\begin{aligned} L &amp;= \\dfrac{Q}{CH^{3{/}2}} = \\dfrac{90}{1.7 \\times 1.6^{1.5}} \\\\ &amp;= \\dfrac{90}{3.44} \\approx 26\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":7,"question":62,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q62 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-07-071","src":"PAST-07-071","text":"The waterway for a bridge on a river in an alluvial plain having a dominant discharge of 3600 cumecs should be","options":[{"key":"a","text":"250 m"},{"key":"b","text":"285 m"},{"key":"c","text":"300 m"},{"key":"d","text":"225 m"}],"answer":"b","explanation":"Lacey's regime waterway is \\[\\begin{aligned} P &amp;= 4.75\\sqrt{Q} = 4.75\\sqrt{3600} \\\\ &amp;= 4.75 \\times 60 = 285\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":7,"question":71,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q71 · 2 marks"},"topic":"ACiE0704"},{"id":"PAST-07-075","src":"PAST-07-075","text":"The Lacey scour depth for a stream carrying a discharge of 3 cumecs per metre width, having a silt factor of 1.2, is","options":[{"key":"a","text":"1.32 m"},{"key":"b","text":"2.64 m"},{"key":"c","text":"3.96 m"},{"key":"d","text":"4.32 m"}],"answer":"b","explanation":"Lacey's scour depth is \\[\\begin{aligned} R &amp;= 1.35\\left(\\dfrac{q^2}{f}\\right)^{1{/}3} \\\\ &amp;= 1.35\\left(\\dfrac{9}{1.2}\\right)^{1{/}3} \\\\ &amp;= 1.35 \\times 1.957 \\approx 2.64\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":7,"question":75,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q75 · 2 marks"},"topic":"ACiE0704"}]},{"name":"Hydropower","questions":[{"id":"PAST-07-004","src":"PAST-07-004","text":"Sloughing is the process of","options":[{"key":"a","text":"progressive erosion"},{"key":"b","text":"subsequent removal of soil grains from within the dam"},{"key":"c","text":"uncontrolled seepage through the dam body"},{"key":"d","text":"progressive removal of soil from the D/S face"}],"answer":"d","explanation":"Sloughing is the progressive removal of soil from the wet downstream face of an earth dam, where seepage emerges. It gradually steepens the slope and can lead to failure.","marks":1,"source":{"kind":"past","set":7,"question":4,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q4 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-07-021","src":"PAST-07-021","text":"In a high head hydropower plant, the velocity of water in the penstock is about","options":[{"key":"a","text":"1 m/s"},{"key":"b","text":"4 m/s"},{"key":"c","text":"7 m/s"},{"key":"d","text":"12 m/s"}],"answer":"c","explanation":"Economic penstock velocities rise with head, from about 2–3 m/s at low heads to roughly 5–7 m/s in high-head plants.","marks":1,"source":{"kind":"past","set":7,"question":21,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q21 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-07-026","src":"PAST-07-026","text":"A gravity dam is most suitable when the foundation is","options":[{"key":"a","text":"weak"},{"key":"b","text":"strong"},{"key":"c","text":"with heavy overburden"},{"key":"d","text":"rocky but cracked"}],"answer":"b","explanation":"A gravity dam is massive and transmits high pressures to its base, so it needs a strong, sound rock foundation. Earth dams suit weaker foundations.","marks":1,"source":{"kind":"past","set":7,"question":26,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q26 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-07-041","src":"PAST-07-041","text":"Which one of the following linings is suitable for shield-driven tunnels, particularly in subaqueous regions?","options":[{"key":"a","text":"Brick lining"},{"key":"b","text":"Stone lining"},{"key":"c","text":"Timber lining"},{"key":"d","text":"Cast iron lining"}],"answer":"d","explanation":"Shield-driven tunnels under water are lined with bolted cast-iron (or steel/precast) segments erected inside the shield tail. They are strong, watertight and immediately load-bearing.","marks":1,"source":{"kind":"past","set":7,"question":41,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q41 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-07-046","src":"PAST-07-046","text":"In a reaction turbine, when steam flows through the fixed blades","options":[{"key":"a","text":"pressure increases while velocity decreases"},{"key":"b","text":"pressure decreases while velocity increases"},{"key":"c","text":"pressure and velocity both decrease"},{"key":"d","text":"pressure and velocity both increase"}],"answer":"b","explanation":"The fixed (guide) blades of a reaction turbine act as nozzles, expanding the fluid so that its pressure falls and its velocity rises. Further expansion occurs in the moving blades.","marks":1,"source":{"kind":"past","set":7,"question":46,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q46 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-07-074","src":"PAST-07-074","text":"If a power station supplies 1000 MWh of electricity to its consumers for a period of two months, then the average demand during the period will be","options":[{"key":"a","text":"1.39 MW"},{"key":"b","text":"1.39 kW"},{"key":"c","text":"0.694 MW"},{"key":"d","text":"0.694 kW"}],"answer":"c","explanation":"Average demand is energy divided by time: \\[\\dfrac{1000\\ \\text{MWh}}{60 \\times 24\\ \\text{h}} \\approx 0.694\\ \\text{MW}\\]","marks":2,"source":{"kind":"past","set":7,"question":74,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q74 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-07-011","src":"PAST-07-011","text":"Which of the following pavements is best for night visibility?","options":[{"key":"a","text":"Gravel road"},{"key":"b","text":"Black top surface"},{"key":"c","text":"WBM"},{"key":"d","text":"Cement concrete"}],"answer":"d","explanation":"The light grey surface of cement concrete reflects headlight beams far better than dark bituminous or dusty gravel and WBM surfaces.","marks":1,"source":{"kind":"past","set":7,"question":11,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q11 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-07-014","src":"PAST-07-014","text":"Compaction is a process in which the change in volume is due to","options":[{"key":"a","text":"Removal of water"},{"key":"b","text":"Removal of air"},{"key":"c","text":"Removal of soil particles"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"Compaction densifies soil by mechanically expelling air from the voids. Expelling water under sustained load is consolidation.","marks":1,"source":{"kind":"past","set":7,"question":14,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q14 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-07-022","src":"PAST-07-022","text":"The ideal shape of a transition curve is","options":[{"key":"a","text":"clothoid"},{"key":"b","text":"cubic spiral"},{"key":"c","text":"cubic parabola"},{"key":"d","text":"lemniscate"}],"answer":"a","explanation":"The clothoid (Euler spiral) has curvature increasing linearly with length (\\(rL = \\text{constant}\\)), so centrifugal acceleration builds up at a uniform rate. That makes it the ideal transition.","marks":1,"source":{"kind":"past","set":7,"question":22,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q22 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-07-025","src":"PAST-07-025","text":"The bench marks are fixed during the","options":[{"key":"a","text":"Preliminary survey"},{"key":"b","text":"Reconnaissance"},{"key":"c","text":"Detailed survey"},{"key":"d","text":"After detailed project report"}],"answer":"c","explanation":"Permanent bench marks are established along the final alignment during the detailed (final location) survey. They are needed for the longitudinal and cross-sections and for setting out.","marks":1,"source":{"kind":"past","set":7,"question":25,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q25 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-07-042","src":"PAST-07-042","text":"The minimum thickness of the base of a flexible pavement is","options":[{"key":"a","text":"10 cm"},{"key":"b","text":"15 cm"},{"key":"c","text":"20 cm"},{"key":"d","text":"25 cm"}],"answer":"a","explanation":"A base course is built at least about 10 cm thick (compacted), so that it spreads the load and can be constructed properly.","marks":1,"source":{"kind":"past","set":7,"question":42,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q42 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-07-045","src":"PAST-07-045","text":"For the movement of vehicles at an intersection of two roads without any interference, the type of grade separator generally preferred is","options":[{"key":"a","text":"delta"},{"key":"b","text":"trumpet"},{"key":"c","text":"diamond interchange"},{"key":"d","text":"clover leaf"}],"answer":"d","explanation":"A full cloverleaf provides free, uninterrupted movement for all turns between two highways by means of loops and ramps.","marks":1,"source":{"kind":"past","set":7,"question":45,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q45 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-07-060","src":"PAST-07-060","text":"The minimum radius of curvature for hair pin bends in hill roads is","options":[{"key":"a","text":"60 m"},{"key":"b","text":"20 m"},{"key":"c","text":"15 m"},{"key":"d","text":"10 m"}],"answer":"c","explanation":"The key takes about 15 m as the minimum radius of the inner curve at hairpin bends on hill roads (IRC quotes 14 m). Hairpin bends are also given flatter gradients and extra width.","marks":1,"source":{"kind":"past","set":7,"question":60,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q60 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-07-069","src":"PAST-07-069","text":"If CBR = 5%, then the resilient modulus as per NRS is","options":[{"key":"a","text":"30 MPa"},{"key":"b","text":"40 MPa"},{"key":"c","text":"50 MPa"},{"key":"d","text":"60 MPa"}],"answer":"c","explanation":"For subgrade \\(\\text{CBR} \\le 5\\%\\), \\[M_R = 10 \\times \\text{CBR} = 50\\ \\text{MPa}\\] For higher CBR, \\(M_R = 17.6 \\times \\text{CBR}^{0.64}\\).","marks":2,"source":{"kind":"past","set":7,"question":69,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q69 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-07-073","src":"PAST-07-073","text":"The total value of extra widening required at a horizontal curve on a two lane hill road of radius 42 m, for a design speed of 50 kmph and for vehicles with wheel base 6 m, is","options":[{"key":"a","text":"0.500 m"},{"key":"b","text":"0.589 m"},{"key":"c","text":"1.669 m"},{"key":"d","text":"0.669 m"}],"answer":"c","explanation":"The mechanical and psychological widenings are \\[\\dfrac{nl^2}{2R} = \\dfrac{2 \\times 36}{84} = 0.857\\ \\text{m}\\] \\[\\begin{aligned} \\dfrac{V}{9.5\\sqrt{R}} &amp;= \\dfrac{50}{9.5 \\times 6.48} \\\\ &amp;= 0.812\\ \\text{m} \\end{aligned}\\] Their total is about 1.669 m.","marks":2,"source":{"kind":"past","set":7,"question":73,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q73 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-07-002","src":"PAST-07-002","text":"The number of female members in the NEC committee of 2079 is","options":[{"key":"a","text":"2"},{"key":"b","text":"3"},{"key":"c","text":"4"},{"key":"d","text":"5"}],"answer":"a","explanation":"The source key gives 2 for the council formed in 2079, and its note adds that the Act intends more women members. The council's composition changes with each term, so check the current NEC list.","marks":1,"source":{"kind":"past","set":7,"question":2,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q2 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-07-010","src":"PAST-07-010","text":"Which of the following shapes is made up of uniform triangles?","options":[{"key":"a","text":"Cone"},{"key":"b","text":"Triangular prism"},{"key":"c","text":"Triangular pyramid"},{"key":"d","text":"None of the above"}],"answer":"b","explanation":"Every cross-section of a triangular prism parallel to its base is the same triangle, whereas the sections of a pyramid or cone shrink towards the apex. This is the key's reasoning.","marks":1,"source":{"kind":"past","set":7,"question":10,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q10 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-07-012","src":"PAST-07-012","text":"In which phase is detailed risk analysis done?","options":[{"key":"a","text":"Feasibility study"},{"key":"b","text":"Planning phase"},{"key":"c","text":"Evaluation phase"},{"key":"d","text":"Implementation phase"}],"answer":"a","explanation":"Risks and uncertainties are analysed in detail at the feasibility stage, before the decision to invest, using sensitivity and risk analysis.","marks":1,"source":{"kind":"past","set":7,"question":12,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q12 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-07-013","src":"PAST-07-013","text":"Project performance consists of","options":[{"key":"a","text":"Time"},{"key":"b","text":"Cost"},{"key":"c","text":"Quality"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Project performance is judged on the triple constraint: completion on time, within budget and to the specified quality.","marks":1,"source":{"kind":"past","set":7,"question":13,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q13 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-07-023","src":"PAST-07-023","text":"The technique for freehand sketching of a circle is","options":[{"key":"a","text":"fixing a fixed point and arc"},{"key":"b","text":"fixing the perimeter"},{"key":"c","text":"fixing the radius only"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Mark the centre and radial lines, fix points at the radius on them, then join the points with short arcs.","marks":1,"source":{"kind":"past","set":7,"question":23,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q23 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-07-024","src":"PAST-07-024","text":"For a financial institution, the most important study of a project to be taken for risk management is","options":[{"key":"a","text":"appraisal"},{"key":"b","text":"environmental and social"},{"key":"c","text":"technical"},{"key":"d","text":"financial and economical"}],"answer":"a","explanation":"Before lending, a financial institution relies on project appraisal: a comprehensive check of technical, financial, economic, market and managerial viability.","marks":1,"source":{"kind":"past","set":7,"question":24,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q24 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-07-043","src":"PAST-07-043","text":"A milestone chart","options":[{"key":"a","text":"shows the interdependencies of various jobs"},{"key":"b","text":"depicts the delay of jobs, if any"},{"key":"c","text":"points outgoing ahead of schedule of jobs, if any"},{"key":"d","text":"none of these"}],"answer":"d","explanation":"A milestone chart only marks key events (milestones) on the bars of a bar chart. It still cannot show job interdependencies or the effect of delays, so none of the statements applies.","marks":1,"source":{"kind":"past","set":7,"question":43,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q43 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-07-044","src":"PAST-07-044","text":"The technique for establishing and maintaining priorities among the various jobs of a project is known as","options":[{"key":"a","text":"Event flow scheduling technique"},{"key":"b","text":"Critical ratio scheduling"},{"key":"c","text":"Slotting technique for scheduling"},{"key":"d","text":"Short interval scheduling"}],"answer":"b","explanation":"Critical ratio scheduling ranks jobs by the ratio of time remaining to work remaining, so priorities are set and continually updated.","marks":1,"source":{"kind":"past","set":7,"question":44,"marks":1,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q44 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-07-063","src":"PAST-07-063","text":"If the initial investment for a machine is Rs 10000 and the depreciation amount per year is Rs 1600, then calculate the book value at the end of 5 years.","options":[{"key":"a","text":"Rs 1500"},{"key":"b","text":"Rs 2000"},{"key":"c","text":"Rs 2500"},{"key":"d","text":"Rs 8000"}],"answer":"b","explanation":"With straight-line depreciation, the book value is \\[\\begin{aligned} B &amp;= 10{,}000 - 5 \\times 1600 \\\\ &amp;= \\text{Rs } 2000 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":7,"question":63,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q63 · 2 marks"},"topic":"AALL1002"},{"id":"PAST-07-072","src":"PAST-07-072","text":"If a is the base amount of expenditure and b is the increase in the operation cost each year over a period of n years, the total cost of maintenance is","options":[{"key":"a","text":"a + (n + 1) b"},{"key":"b","text":"a + (n − 1) b"},{"key":"c","text":"a × (n − 1) b"},{"key":"d","text":"a − (n − 1) b"}],"answer":"b","explanation":"With a uniform gradient the cost is a in the first year and grows by b each year, so the cost in the n-th year is a + (n − 1)b.","marks":2,"source":{"kind":"past","set":7,"question":72,"marks":2,"date":"2080 Mangsir 25","shift":"1st shift","reference":"Past Paper Set 7, Q72 · 2 marks"},"topic":"AALL1002"}]}]};
